                final String errorMessage =
                    String.format(
                        "Withdrawals root from the local payload (%s) was different from the proposed payload (%s)",
                        localWithdrawalsRoot, withdrawalsRoot);
                throw new BuilderBidValidationException(errorMessage);
              }
            });

